const mediaGrid = document.querySelector('[data-media-grid]');
document.querySelectorAll('[data-media-view]').forEach((button) => {
button.addEventListener('click', () => {
const listMode = button.dataset.mediaView === 'list';
mediaGrid?.classList.toggle('media-grid--list', listMode);
document.querySelectorAll('[data-media-view]').forEach((toggle) => {
toggle.setAttribute('aria-pressed', toggle === button ? 'true' : 'false');
});
});
});
document.querySelectorAll('[data-media-select]').forEach((button) => {
button.addEventListener('click', () => {
const selection = {
id: Number(button.dataset.mediaSelect),
title: button.dataset.mediaTitle ?? '',
alt: button.dataset.mediaAlt ?? '',
mimeType: button.dataset.mediaMime ?? '',
url: button.dataset.mediaUrl ?? '',
publicUrl: button.dataset.mediaPublicUrl ?? '',
};
const status = document.querySelector('[data-media-selection-status]');
if (status) status.textContent = `Imagem selecionada: ${selection.title}.`;
window.dispatchEvent(new CustomEvent('moves:media-selected', { detail: selection }));
if (window.opener && !window.opener.closed) {
window.opener.postMessage({ type: 'moves:media-selected', media: selection }, window.location.origin);
window.close();
}
});
});
let mediaPickerWindow = null;
let mediaPickerContext = null;
document.querySelectorAll('[data-open-media-picker]').forEach((button) => {
button.addEventListener('click', () => {
const form = button.closest('form');
if (!form) return;
const editor = form.movesEditor ?? null;
const mode = button.hasAttribute('data-media-picker-cover') ? 'cover' : 'insert';
if (mode === 'insert' && !editor) return;
if (mode === 'insert') editor.saveSelection();
mediaPickerContext = { form, editor, mode };
mediaPickerWindow = window.open(
button.dataset.pickerUrl || `${window.location.origin}/admin/media/picker`,
'movesMediaPicker',
'popup,width=1180,height=820,resizable=yes,scrollbars=yes'
);
if (!mediaPickerWindow) {
mediaPickerContext = null;
window.alert('Permita a abertura de janelas para selecionar uma imagem.');
}
});
});
window.addEventListener('message', (event) => {
if (event.origin !== window.location.origin || event.source !== mediaPickerWindow
|| event.data?.type !== 'moves:media-selected' || !mediaPickerContext
) return;
const media = event.data.media;
if (!media || !Number.isSafeInteger(media.id) || media.id < 1
|| !['image/jpeg', 'image/png', 'image/webp'].includes(media.mimeType)
) return;
const privateUrl = new URL(String(media.url || ''), window.location.origin);
const publicUrl = new URL(String(media.publicUrl || ''), window.location.origin);
if (privateUrl.origin !== window.location.origin || publicUrl.origin !== window.location.origin
|| privateUrl.pathname !== `/admin/media/${media.id}/file`
|| publicUrl.pathname !== `/media/${media.id}`
) return;
if (mediaPickerContext.mode === 'cover') {
const field = mediaPickerContext.form.querySelector('[name="cover_image"]');
if (field) {
field.value = publicUrl.pathname;
field.dispatchEvent(new Event('input', { bubbles: true }));
}
} else {
mediaPickerContext.editor.restore();
mediaPickerContext.editor.insertImage(privateUrl.pathname, String(media.alt || ''), '');
}
mediaPickerWindow = null;
mediaPickerContext = null;
});